using OneAudio;
using OneAudio.Tests;

/// <summary>
/// NativeAOT check for the Ogg Vorbis path: the stream is generated by the same code the tests use (random but valid
/// codebooks, floors and residues), so the file is our own bytes. It is decoded, sought and played through the mixer.
/// </summary>
internal static class VorbisSmoke
{
    public static int Run()
    {
        var builder = new VorbisStreamBuilder { Channels = 2, SampleRate = 44_100, Seed = 7 };
        byte[] file = builder.BuildFile(count: 40);

        var registry = new AudioCodecRegistry().AddOgg().AddVorbis();
        using var decoder = AudioDecoder.Open(new MemoryStream(file), registry);
        if (decoder.Format.SampleRate != 44_100 || decoder.Format.Channels != 2) return Fail("vorbis format");
        if (!decoder.CanSeek || decoder.LengthFrames <= 0) return Fail("vorbis length");

        var block = new float[1024 * 2];
        long frames = 0;
        float peak = 0;
        int n;
        while ((n = decoder.Read(block)) > 0)
        {
            frames += n;
            for (int i = 0; i < n * 2; i++) peak = MathF.Max(peak, MathF.Abs(block[i]));
        }
        if (frames != decoder.LengthFrames) return Fail($"vorbis decoded {frames} of {decoder.LengthFrames} frames");
        // The residues are random, so the level is arbitrary (and may exceed full scale); it must be audible and finite.
        if (!(peak > 0f) || !float.IsFinite(peak)) return Fail($"vorbis peak {peak}");

        decoder.Seek(decoder.LengthFrames / 2);
        if (decoder.Read(block) <= 0) return Fail("vorbis read after seek");
        decoder.Seek(0);

        var clip = AudioClip.FromDecoder(decoder);
        var mixer = new AudioMixer(new MixerOptions { SampleRate = 44_100, Channels = 2 });
        if (!mixer.Play(new PlayParams(clip) { Gain = 0.5f }).IsValid) return Fail("vorbis play");
        var out2 = new float[512 * 2];
        float mixPeak = 0;
        for (int pass = 0; pass < 8; pass++)
        {
            mixer.Render(out2);
            foreach (float s in out2) mixPeak = MathF.Max(mixPeak, MathF.Abs(s));
        }
        if (!(mixPeak > 0f)) return Fail("vorbis mix is silent");

        Console.WriteLine($"ok: vorbis {frames} frames decoded, mixed peak {mixPeak:F3}");
        return 0;
    }

    private static int Fail(string why)
    {
        Console.Error.WriteLine("FAIL: " + why);
        return 1;
    }
}
